import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:uuid/uuid.dart';
import 'package:translator/translator.dart';
import 'package:flutter/material.dart';

class Utils { static String genId()=> Uuid().v4().substring(0,8); static int now()=> DateTime.now().millisecondsSinceEpoch; }
class Post { String id,text,user,image; int time; List<String> likes; bool isPremium,hidden; Post({this.id="",this.text="",this.user="",this.time=0,this.image="",this.likes=const [],this.isPremium=false,this.hidden=false}); Map<String,dynamic> toMap()=>{"id":id,"text":text,"user":user,"time":time,"image":image,"likes":likes,"isPremium":isPremium,"hidden":hidden}; factory Post.fromMap(Map<String,dynamic> m)=> Post(id:m['id']??"",text:m['text']??"",user:m['user']??"",time:m['time']??0,likes:List<String>.from(m['likes']??[])); }
class VideoTikTokModel { String id,titre,owner,url,sound; List<String> hashtags,vues,likes,partages,saves; List<dynamic> comments,gifts; VideoTikTokModel({this.id="",this.titre="",this.owner="",this.url="",this.sound="",this.hashtags=const [],this.vues=const [],this.likes=const [],this.partages=const [],this.saves=const [],this.comments=const [],this.gifts=const []}); Map<String,dynamic> toMap()=>{"id":id,"titre":titre,"owner":owner,"url":url,"sound":sound,"hashtags":hashtags,"vues":vues,"likes":likes,"partages":partages,"saves":saves,"comments":comments,"gifts":gifts,"time":Utils.now()}; factory VideoTikTokModel.fromMap(Map<String,dynamic> m)=> VideoTikTokModel(id:m['id']??"",titre:m['titre']??"",owner:m['owner']??"",vues:List<String>.from(m['vues']??[]),likes:List<String>.from(m['likes']??[])); }

class PostsService { static final db=FirebaseFirestore.instance; static Future<void> creerPost(String t,String u,{String img=""}) async { final p=Post(id:Utils.genId(),text:t,user:u,time:Utils.now(),image:img); await db.collection("posts").doc(p.id).set(p.toMap()); } static Stream<List<Post>> postsFeed(){ try{ return db.collection("posts").where("hidden",isEqualTo:false).orderBy("time",descending:true).snapshots().map((s)=> s.docs.map((d)=> Post.fromMap(d.data())).toList()); }catch(_){ return Stream.value([Post(id:"1", text:"Belle journée pour explorer le parc! ☀️ Le pique-nique d'automne est enfin là, parfait pour un café et des discussions entre amis.", user:"Thomas Bernard", likes:["a","b"])]); } } static Future<void> supprimerPost(String id) async => await db.collection("posts").doc(id).delete(); }
class ReactionsService { static final db=FirebaseFirestore.instance; static Future<void> likerPost(String id,String u) async => await db.collection("posts").doc(id).update({"likes":FieldValue.arrayUnion([u])}); static Future<void> unlikerPost(String id,String u) async => await db.collection("posts").doc(id).update({"likes":FieldValue.arrayRemove([u])}); }
class BalanceService { static final db=FirebaseFirestore.instance; static Future<int> getSolde(String p) async { try{ var d=await db.collection("users").doc(p).get(); return d.data()?['solde']??2000; }catch(_){ return 2000; } } static Future<void> rechargerSolde(String p,int m) async { var s=await getSolde(p); try{ await db.collection("users").doc(p).set({"solde":s+m}, SetOptions(merge:true)); }catch(_){} } static Future<bool> retirerSolde(String p,int m) async { var s=await getSolde(p); if(s<m) return false; try{ await db.collection("users").doc(p).update({"solde":s-m}); }catch(_){} return true; } }
class PubslookService { static final db=FirebaseFirestore.instance; static List<VideoTikTokModel> videos=[]; static List<VideoTikTokModel> fyp=[]; static Stream<List<VideoTikTokModel>> streamVideos(){ try{ return db.collection("videos").snapshots().map((s){ videos=s.docs.map((d)=> VideoTikTokModel.fromMap(d.data())).toList(); fyp=[...videos]..sort((a,b)=> b.vues.length.compareTo(a.vues.length)); return videos; }); }catch(_){ return Stream.value([]); } } static List<VideoTikTokModel> forYou(){ if(fyp.isEmpty) fyp=[...videos]; return fyp; } static Future<void> voir(String id,String u) async { try{ await db.collection("videos").doc(id).update({"vues":FieldValue.arrayUnion([u])}); }catch(_){} } static Future<void> like(String id,String u) async { try{ await db.collection("videos").doc(id).update({"likes":FieldValue.arrayUnion([u])}); }catch(_){} } static Future<void> envoyerGift(String vId,String from,String type,int value) async { try{ await db.collection("videos").doc(vId).update({"gifts":FieldValue.arrayUnion([{"from":from,"type":type,"value":value}])}); }catch(_){} await BalanceService.retirerSolde(from,value); } static Future<bool> creerVideo(String titre,String owner,String url,{String sound="",List<String> tags=const [],int prix=200}) async { if(!await BalanceService.retirerSolde(owner,prix)) return false; final v=VideoTikTokModel(id:Utils.genId(),titre:titre,owner:owner,url:url,sound:sound,hashtags:tags); try{ await db.collection("videos").doc(v.id).set(v.toMap()); }catch(_){} return true; } }
class SecurityService { static final db=FirebaseFirestore.instance; static Future<void> signalerPost(String postId,String raison,{String userId="Admin"}) async { try{ await db.collection("reports").add({"postId":postId,"raison":raison,"reporter":userId,"time":FieldValue.serverTimestamp()}); var r=await db.collection("reports").where("postId",isEqualTo:postId).get(); if(r.size>=5) await db.collection("posts").doc(postId).update({"hidden":true}); }catch(_){} } static Future<void> supprimerMonCompte(Function onDone) async { try{ var uid=FirebaseAuth.instance.currentUser?.uid??"Admin"; await FirebaseAuth.instance.currentUser?.delete(); await db.collection("users").doc(uid).delete(); }catch(_){} onDone(); } }
class TranslationService { static final LANGUES={"fr":"🇫🇷 Français","en":"🇺🇸 English","fon":"🇧🇯 Fɔngbè","yo":"🇳🇬 Yorùbá","ig":"🇳🇬 Igbo","ha":"🇳🇬 Hausa","sw":"🇹🇿 Kiswahili","ar":"🇸🇦 العربية","pt":"🇵🇹 Português","es":"🇪🇸 Español","de":"🇩🇪 Deutsch","zh":"🇨🇳 中文","hi":"🇮🇳 हिन्दी","tr":"🇹🇷 Türkçe","ru":"🇷🇺 Русский","it":"🇮🇹 Italiano","nl":"🇳🇱 Nederlands","ja":"🇯🇵 日本語","ko":"🇰🇷 한국어","ln":"🇨🇩 Lingala"}; static ValueNotifier<String> langueActuelle=ValueNotifier("fr"); static final _translator=GoogleTranslator(); static Future<void> changerLangue(String code) async { langueActuelle.value=code; try{ var uid=FirebaseAuth.instance.currentUser?.uid; if(uid!=null) await FirebaseFirestore.instance.collection("users").doc(uid).update({"lang":code}); }catch(_){} } static Future<void> traduireTexte(String texte,String vers,Function(String) onResult) async { if(["fon","yo","ig","ln","ha"].contains(vers)){ onResult(texte); return; } try{ var r=await _translator.translate(texte,from:'fr',to:vers); onResult(r.text); }catch(_){ onResult(texte); } } }
class FriendsService { static Future<void> ajouterAmi(String a,String b) async {} static Future<void> retirerAmi(String a,String b) async {} }
class CommentsService { static Future<void> ajouterComment(String pId,String t,String u) async {} }
